WITH r AS (
  SELECT sum(sr_return_quantity)::numeric AS q
  FROM store_returns
  WHERE sr_returned_date_sk IN (SELECT d_date_sk FROM date_dim WHERE d_year=2002 AND d_moy=9)
), s AS (
  SELECT sum(ss_quantity)::numeric AS q
  FROM store_sales
  WHERE ss_sold_date_sk IN (SELECT d_date_sk FROM date_dim WHERE d_year=2002 AND d_moy=9)
)
SELECT round(100.0 * (SELECT q FROM r) / (SELECT q FROM s), 2) AS store_return_rate;
